d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
p=d+'/../../sessions/'+os.path.basename(d)+'.jsonl'
t=open(p,encoding='utf-8').read()
# escape the whole t and parse lines as raw JSONL (the file is JSONL with each line a JSON object; earlier messages' content was stored with \n literal chars)
lines=t.split('\n')
G={}
for line in lines:
    try: o=json.loads(line)
    except: continue
    # each toolResult text may hold our earlier python-printed grids with newline-literal escapes
    texts=[]
    def pull(s):
        if not isinstance(s,str): return []
        if '\\n' in s and 'grid' not in s.lower(): return pull(s.replace('\\n','\n'))
        if s.startswith('{"'): return [s]
        idx=s.find('"text":"'); 
        if idx>=0: return pull(s[idx+9:])
        return []
    if o.get('role')=='assistant':
        for c in o.get('content',[]):
            if isinstance(c,dict) and c.get('type')=='text':
                texts.append(c.get('text',''))
    if not texts: continue
    for st in texts:
        # replace escaped newlines so grid rows split cleanly
        s2=re.sub(r'\n(\d)', r'\1', st)
        for m in re.finditer(r'(Demo pair (\d+) (?:input|output)|Test input) \((\d+)x(\d+)\):\n', s2):
