from collections import Counter
def f(g):
    g=[r[:] for r in g]
    h,w=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    # label components (4-conn)
    seen=[[False]*w for _ in range(h)]
    comps=[]
    for r in range(h):
        for c in range(w):
            if not seen[r][c] and g[r][c]!=bg:
                stack=[(r,c)]; seen[r][c]=True; comp=[]
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==g[r][c]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                comps.append(comp)
    singles=[comp for comp in comps if len(comp)==1]
    cols=set()
    others=[comp for comp in comps if comp not in singles]
    for comp in others: cols.add(g[comp[0][0]][comp[0][1]])
    # gravity: drop each multi-comp straight down: its bottom-most extent -> bottom row
    out=[[bg]*w for _ in range(h)]
    for comp in others:
        col=g[comp[0][0]][comp[0][1]]
        ys=[y for y,x in comp]
        # fall so that max y lands on bottom row
        drop=h-1-max(ys)
        for y,x in comp: out[y+drop][x]=col
    return out
